bool hasReplayableRawRenderSettings(const LC_DwgAdvancedMetadata &metadata,
                                    std::uint32_t handle,
                                    DRW_RenderSettings::Kind kind,
                                    DRW::Version targetVersion) {
  if (handle == 0)
    return false;
  const auto matchesKind =
      [kind](const LC_DwgAdvancedMetadata::RawObjectRecord &record) {
        switch (kind) {
        case DRW_RenderSettings::Settings:
          return record.recordName == "RENDERSETTINGS" ||
                 record.recordName == "ACDBRENDERSETTINGS" ||
                 record.className == "AcDbRenderSettings";
        case DRW_RenderSettings::Entry:
          return record.recordName == "RENDERENTRY" ||
                 record.recordName == "ACDBRENDERENTRY" ||
                 record.className == "AcDbRenderEntry";
        case DRW_RenderSettings::Environment:
          return record.recordName == "RENDERENVIRONMENT" ||
                 record.recordName == "ACDBRENDERENVIRONMENT" ||
                 record.className == "AcDbRenderEnvironment";
        case DRW_RenderSettings::Global:
          return record.recordName == "RENDERGLOBAL" ||
                 record.recordName == "ACDBRENDERGLOBAL" ||
                 record.className == "AcDbRenderGlobal";
        case DRW_RenderSettings::RapidRT:
          return record.recordName == "RAPIDRTRENDERSETTINGS" ||
                 record.recordName == "ACDBRAPIDRTRENDERSETTINGS" ||
                 record.className == "AcDbRapidRTRenderSettings";
        case DRW_RenderSettings::MentalRay:
          return record.recordName == "MENTALRAYRENDERSETTINGS" ||
                 record.recordName == "ACDBMENTALRAYRENDERSETTINGS" ||
                 record.className == "AcDbMentalRayRenderSettings";
        default:
          return false;
        }
      };
  for (const auto &record : metadata.rawObjects()) {
    if (record.handle == handle && record.version == targetVersion &&
        matchesKind(record) &&
        LC_DwgAdvancedMetadata::rawReplayBlocker(record) ==
            LC_DwgAdvancedMetadata::ReplayBlocker::None)
      return true;
  }
  return false;
}

