template <typename StableReference>
bool hasReplayableRawLightList(const LC_DwgAdvancedMetadata &metadata,
                               std::uint32_t handle, DRW::Version targetVersion,
                               StableReference stableReference) {
  if (handle == 0)
    return false;
  const auto lightListCount = std::count_if(
      metadata.lightLists().cbegin(), metadata.lightLists().cend(),
      [handle](const auto &record) { return record.handle == handle; });
  if (lightListCount != 1)
    return false;
  const auto lightList = std::find_if(
      metadata.lightLists().cbegin(), metadata.lightLists().cend(),
      [handle](const auto &record) { return record.handle == handle; });
  if (lightList == metadata.lightLists().cend())
    return false;
  const auto rawCarrierCount = std::count_if(
      metadata.rawObjects().cbegin(), metadata.rawObjects().cend(),
      [handle, targetVersion](const auto &record) {
        return !record.isEntity && record.handle == handle &&
               record.version == targetVersion &&
               isLightListRawObject(record) &&
               LC_DwgAdvancedMetadata::rawReplayBlocker(record) ==
                   LC_DwgAdvancedMetadata::ReplayBlocker::None;
      });
  if (rawCarrierCount != 1 || !stableReference(lightList->parentHandle) ||
      !stableReference(lightList->xDictHandle) ||
      !std::all_of(lightList->reactorHandles.cbegin(),
                   lightList->reactorHandles.cend(), stableReference)) {
    return false;
  }

  for (const auto &light : lightList->lights) {
    if (light.handle == 0 || !stableReference(light.handle))
      return false;
    const auto lightRecord =
        std::find_if(metadata.lights().cbegin(), metadata.lights().cend(),
                     [&light](const auto &candidate) {
                       return candidate.handle == light.handle;
                     });
    if (lightRecord == metadata.lights().cend() ||
        lightRecord->replayState !=
            LC_DwgAdvancedMetadata::ReplayState::ReplayAllowed)
      return false;
  }
  return true;
}

