DRW_Dictionary
dictionaryFromMetadata(const LC_DwgAdvancedMetadata::DictionaryRecord &record) {
  DRW_Dictionary dictionary;
  dictionary.handle = record.handle;
  dictionary.parentHandle = record.parentHandle;
  dictionary.cloning = record.cloning;
  dictionary.hardOwner = record.hardOwner;
  dictionary.name = record.name;
  dictionary.appData = record.appData;
  restoreTableEntryExtData(dictionary, record.extData);
  dictionary.reactorHandles = record.reactorHandles;
  dictionary.xDictHandle = record.xDictHandle;
  dictionary.setDwgCommonObjectState(record.numReactors, record.xDictFlag,
                                     record.hasDsData);
  dictionary.m_entries.reserve(record.entries.size());
  for (const auto &er : record.entries) {
    DRW_Dictionary::Entry entry;
    entry.m_name = er.name;
    entry.m_handle = er.handle;
    dictionary.m_entries.push_back(std::move(entry));
  }
  return dictionary;
}

