DRW_PointCloudColorMap pointCloudColorMapFromMetadata(
    const LC_DwgAdvancedMetadata::PointCloudColorMapRecord &record) {
  DRW_PointCloudColorMap colorMap;
  colorMap.handle = record.handle;
  colorMap.parentHandle = record.parentHandle;
  colorMap.appData = record.appData;
  restoreTableEntryExtData(colorMap, record.extData);
  colorMap.m_classVersion = record.classVersion;
  colorMap.m_defaultIntensityColorScheme = record.defaultIntensityColorScheme;
  colorMap.m_defaultElevationColorScheme = record.defaultElevationColorScheme;
  colorMap.m_defaultClassificationColorScheme =
      record.defaultClassificationColorScheme;
  colorMap.m_colorRampCount = record.declaredColorRampCount;
  colorMap.m_classificationColorRampCount =
      record.declaredClassificationColorRampCount;
  const auto copyRamps = [](const auto &source, auto &destination) {
    destination.reserve(source.size());
    for (const auto &ramp : source) {
      DRW_PointCloudColorMapRamp copied;
      copied.m_classVersion = ramp.classVersion;
      copied.m_rampCount = ramp.declaredColorCount;
      copied.m_colorSchemes = ramp.colorSchemes;
      destination.push_back(std::move(copied));
    }
  };
  copyRamps(record.colorRamps, colorMap.m_colorRamps);
  copyRamps(record.classificationColorRamps,
            colorMap.m_classificationColorRamps);
  colorMap.reactorHandles = record.reactorHandles;
  colorMap.xDictHandle = record.xDictHandle;
  colorMap.setDwgCommonObjectState(record.numReactors, record.xDictFlag,
                                   record.hasDsData);
  return colorMap;
}

