      const auto writePlotSettings = [&](DRW_PlotSettings plotSettings,
                                         bool overlayActiveSettings,
                                         std::uint32_t generatedOrdinal) {
        const std::uint32_t sourceHandle = plotSettings.handle;
        remapEntry(plotSettings);
        const bool plotSettingsValid = sanitizeCommonObjectReferences(
            plotSettings, "PLOTSETTINGS common reference");
        if (!plotSettingsValid)
          m_writeFailed = true;
        if (m_dwgW->getVersion() >= DRW::AC1018) {
          plotSettings.plotViewHandle.ref = remapViewHandle(
              plotSettings.plotViewHandle.ref, "PLOTSETTINGS plot VIEW");
        } else {
          plotSettings.plotViewHandle.ref = 0;
        }
        if (m_dwgW->getVersion() > DRW::AC1018) {
          sanitizeObjectHandle(plotSettings.shadePlotHandle.ref,
                               "PLOTSETTINGS shade plot");
        } else {
          plotSettings.shadePlotHandle.ref = 0;
        }
        if (plotSettingsValid && overlayActiveSettings &&
            graphicPlotSettings != nullptr) {
          overlayActivePlotSettings(plotSettings, *graphicPlotSettings);
        }
        const bool wrote =
            plotSettingsValid &&
            (sourceHandle == 0
                 ? writeDwgObjectWithCompletion(
                       RS_FilterDXFRW_DwgWriteIdentityRegistry::
                           DwgWriteSourceKind::GeneratedChild,
                       0,
                       [&plotSettings, this] {
                         return m_dwgW->writePlotSettings(&plotSettings);
                       },
                       [] { return true; }, generatedOrdinal)
                 : writeDwgObject(RS_FilterDXFRW_DwgWriteIdentityRegistry::
                                      DwgWriteSourceKind::Object,
                                  sourceHandle, [&plotSettings, this] {
                                    return m_dwgW->writePlotSettings(
                                        &plotSettings);
                                  }));
        if (plotSettingsValid && !wrote) {
          RS_DEBUG->print(RS_Debug::D_WARNING,
                          "RS_FilterDXFRW: failed to write DWG "
                          "PLOTSETTINGS");
          m_writeFailed = true;
        }
      };
