/**
 * Converts a native unicode string into a DXF encoded string.
 *
 * DXF endoding includes the following special sequences:
 * - %%%c for a diameter sign
 * - %%%d for a degree sign
 * - %%%p for a plus/minus sign
 */
QString RS_FilterDXFRW::toDxfString(const QString &str) {
  QString res;
  res.reserve(str.length() + 16);

  for (const QChar &qchar : str) {
    switch (qchar.unicode()) {
    case 0x0A:
      res.append(uR"(\P)");
      break;
    case 0x2205:
    case 0x2300:
      res.append(u"%%C");
      break;
    case 0x00B0:
      res.append(u"%%D");
      break;
    case 0x00B1:
      res.append(u"%%P");
      break;
    default:
      res.append(qchar);
      break;
    }
  }
  return res;
}

/**
 * Converts a DXF encoded string into a native Unicode string.
 */
QString RS_FilterDXFRW::toNativeString(const QString &data) {
  QString res;
  const int n = data.length();

  // Ignore font tags:
  int j = 0;
  for (int i = 0; i < n; ++i) {
    // Need at least "{\X" available — bounds-check before any at(i+N).
    if (i + 2 >= n)
      break;
    if (data.at(i).unicode() != 0x7B)
      continue; // is '{' ?
    if (data.at(i + 1).unicode() != 0x5c)
      continue; // and is "{\" ?
    const ushort tagChar = data.at(i + 2).unicode();
    if (tagChar != 0x66 && tagChar != 0x48 && tagChar != 0x43)
      continue; // "\f" "\H" "\C"

    // found tag, append parsed part
    res.append(data.mid(j, i - j));
    qsizetype pos = data.indexOf(QChar(0x7D), i + 3); // find '}'
    if (pos < 0)
      break; //'}' not found
    QString tmp = data.mid(i + 1, pos - i - 1);
    do {
      qsizetype semi = tmp.indexOf(QChar(0x3B), 0); // find ';'
      if (semi < 0)
        break; // malformed: no ';' — bail to avoid infinite loop
      tmp.remove(0, semi + 1);
    } while (tmp.startsWith(QLatin1StringView("\\f")) ||
             tmp.startsWith(QLatin1StringView("\\H")) ||
             tmp.startsWith(QLatin1StringView("\\C")));
    res.append(tmp);
    i = pos;
    j = pos + 1;
  }
  res.append(data.mid(j));

  // AutoCAD caret convention: ^X → chr((X-64) mod 126); ^Space → '^'
  // literal. Mirrors ezdxf tools/text.py:501. Run BEFORE the \P/\~ pass
  // so ^J (LF), ^M (CR), ^I (TAB) decode first; also subsumes the prior
  // hard-coded "^I → 4 spaces" rule with the general formula (^I → TAB).
  QString caretDecoded;
  caretDecoded.reserve(res.size());
  for (int k = 0; k < res.size(); ++k) {
    const QChar ch = res.at(k);
    if (ch.unicode() == 0x5E /* '^' */ && k + 1 < res.size()) {
      const QChar nx = res.at(k + 1);
      if (nx.unicode() == 0x20) {
        caretDecoded.append(QChar(0x5E)); // ^space → literal ^
      } else {
        const int code = (static_cast<int>(nx.unicode()) - 64) % 126;
        caretDecoded.append(
            QChar(static_cast<ushort>(code < 0 ? code + 126 : code)));
      }
      ++k; // consume the X
    } else {
      caretDecoded.append(ch);
    }
  }
  res = std::move(caretDecoded);

  // Replace literal escape sequences. Each replace() mutates in place;
  // the prior `res = res.replace(...)` was an unnecessary self-assignment.
  res.replace(QLatin1StringView("\\P"), QLatin1StringView("\n")); // line feed
  res.replace(QLatin1StringView("\\~"), QLatin1StringView(" "));  // space
  // diameter / degree / plus-minus — case-insensitive match of %%c / %%C etc.
  // (RLZ: Empty_set is 0x2205, diameter is 0x2300 — needs to be in all fonts.)
  res.replace(QLatin1StringView("%%c"), QStringLiteral("⌀"),
              Qt::CaseInsensitive);
  res.replace(QLatin1StringView("%%d"), QStringLiteral("°"),
              Qt::CaseInsensitive);
  res.replace(QLatin1StringView("%%p"), QStringLiteral("±"),
              Qt::CaseInsensitive);

  return res;
}

/**
 * Converts the given number from a DXF file into an AngleFormat enum.
 *
 * @param num $DIMAUNIT from DXF (0: decimal deg, 1: deg/min/sec, 2: gradians,
 *                                3: radians, 4: surveyor's units)
 *
 * @ret Matching AngleFormat enum value.
 */
RS2::AngleFormat RS_FilterDXFRW::numberToAngleFormat(int num) {
  switch (num) {
  default:
  case 0:
    return RS2::DegreesDecimal;
  case 1:
    return RS2::DegreesMinutesSeconds;
  case 2:
    return RS2::Gradians;
  case 3:
    return RS2::Radians;
  case 4:
    return RS2::Surveyors;
  }
}

/**
 * Converts AngleFormat enum to DXF number.
 */
int RS_FilterDXFRW::angleFormatToNumber(RS2::AngleFormat af) {
  switch (af) {
  default:
  case RS2::DegreesDecimal:
    return 0;
  case RS2::DegreesMinutesSeconds:
    return 1;
  case RS2::Gradians:
    return 2;
  case RS2::Radians:
    return 3;
  case RS2::Surveyors:
    return 4;
  }
}

/**
 * converts a DXF unit setting (e.g. INSUNITS) to a unit enum.
 */
RS2::Unit RS_FilterDXFRW::numberToUnit(int num) {
  switch (num) {
  default:
  case 0:
    return RS2::None;
  case 1:
    return RS2::Inch;
  case 2:
    return RS2::Foot;
  case 3:
    return RS2::Mile;
  case 4:
    return RS2::Millimeter;
  case 5:
    return RS2::Centimeter;
  case 6:
    return RS2::Meter;
  case 7:
    return RS2::Kilometer;
  case 8:
    return RS2::Microinch;
  case 9:
    return RS2::Mil;
  case 10:
    return RS2::Yard;
  case 11:
    return RS2::Angstrom;
  case 12:
    return RS2::Nanometer;
  case 13:
    return RS2::Micron;
  case 14:
    return RS2::Decimeter;
  case 15:
    return RS2::Decameter;
  case 16:
    return RS2::Hectometer;
  case 17:
    return RS2::Gigameter;
  case 18:
    return RS2::Astro;
  case 19:
    return RS2::Lightyear;
  case 20:
    return RS2::Parsec;
  }
  return RS2::None;
}

/**
 * Converts a unit enum into a DXF unit number e.g. for INSUNITS.
 */
int RS_FilterDXFRW::unitToNumber(RS2::Unit unit) {
  switch (unit) {
  default:
  case RS2::None:
    return 0;
  case RS2::Inch:
    return 1;
  case RS2::Foot:
    return 2;
  case RS2::Mile:
    return 3;
  case RS2::Millimeter:
    return 4;
  case RS2::Centimeter:
    return 5;
  case RS2::Meter:
    return 6;
  case RS2::Kilometer:
    return 7;
  case RS2::Microinch:
    return 8;
  case RS2::Mil:
    return 9;
  case RS2::Yard:
    return 10;
  case RS2::Angstrom:
    return 11;
  case RS2::Nanometer:
    return 12;
  case RS2::Micron:
    return 13;
  case RS2::Decimeter:
    return 14;
  case RS2::Decameter:
    return 15;
  case RS2::Hectometer:
    return 16;
  case RS2::Gigameter:
    return 17;
  case RS2::Astro:
    return 18;
  case RS2::Lightyear:
    return 19;
  case RS2::Parsec:
    return 20;
  }
  return 0;
}

/**
 * Checks if the given variable is two-dimensional (e.g. $LIMMIN).
 */
bool RS_FilterDXFRW::isVariableTwoDimensional(const QString &var) {
  if (var == "$LIMMIN" || var == "$LIMMAX" || var == "$PLIMMIN" ||
      var == "$PLIMMAX" || var == "$GRIDUNIT" || var == "$VIEWCTR") {
    return true;
  } else {
    return false;
  }
}

void RS_FilterDXFRW::addPolylineSegment(
    RS_Polyline &polyline, const RS_Vector &prev_pos, const RS_Vector &curr_pos,
    const double segmentBulge, const double nextBulge,
    const std::vector<std::shared_ptr<DRW_Variant>> &extData) {
  bool isLcData = false;
  double yRadius = 0.0;

  // Issue #1946: LibreCAD may use elliptic arcs internally, but dxf file saving
  // uses arcs only. Minor radius of elliptic is saved as DRW_Variant::content
  // The content is flagged as "LibreCAD"
  for (const std::shared_ptr<DRW_Variant> &var : extData) {
    if (var == nullptr)
      continue;
    if (var->code() == 1001) {
      std::string marker;
      isLcData = readXDataMarker(var.get(), marker) == XDataReadResult::Valid &&
                 marker == "LibreCad";
    } else if (isLcData && var->code() == 1040) {
      double radius = 0.0;
      if (readXDataDouble(var.get(), 1040, radius) == XDataReadResult::Valid) {
        yRadius = radius;
      } else {
        isLcData = false;
      }
    }
  }
  bool isElliptic = yRadius > RS_TOLERANCE;

  if (isElliptic) {
    std::unique_ptr<RS_Arc> arc{
        RS_Polyline::arcFromBulge(prev_pos, curr_pos, segmentBulge)};
    if (arc != nullptr && arc->getRadius() >= RS_TOLERANCE) {
      double radius = arc->getRadius();
      double scaleRatio = yRadius / radius;
      RS_Ellipse *ellipse =
          RS_Polyline::convertToEllipse(std::make_pair(arc.get(), scaleRatio));
      if (ellipse != nullptr) {
        ellipse->setParent(&polyline);
        // ellipse->setSelected(polyline.isSelected());
        ellipse->setPen(RS_Pen(RS2::FlagInvalid));
        ellipse->setLayer(nullptr);
        polyline.addEntity(ellipse);
        polyline.getData().endpoint = curr_pos;
        polyline.setNextBulge(nextBulge);
        return;
      }
    }
  }

  // A malformed LibreCAD elliptic sidecar must not leave a gap in an
  // otherwise valid polyline. addVertex consumes the current outgoing bulge
  // and stores the following vertex's bulge for the next segment.
  polyline.addVertex(curr_pos, nextBulge, false);
}

